/* 홈 화면은 별도 고정 레이어가 아니라 Workspace 안의 본문 뷰로 동작한다.
   따라서 시장정보 사이드바가 열리거나 패널 폭이 바뀌어도 본문과 함께 자연스럽게 줄어든다. */
#gaemiWorkspace #mainContent #mainHeroView {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  right: auto !important;
  z-index: 30;
}

[data-panel-header-toggle][aria-hidden="true"] {
  display: none !important;
}

/* 패널은 항상 본문 오른쪽에 고정한다. */
body.panel-resizing, body.panel-resizing * { cursor: col-resize !important; }
body.panel-resizing * { user-select: none !important; }
body.left-panel-resizing, body.left-panel-resizing * { cursor: col-resize !important; }
body.left-panel-resizing * { user-select: none !important; }


@media (max-width: 1023px) {
  #leftMarketSidebar.market-sidebar {
    width: min(300px, 82vw);
    flex-basis: min(300px, 82vw);
  }
  body.left-market-closed #leftMarketSidebar.market-sidebar {
    width: 0;
    flex-basis: 0;
  }
  body.right-panel-open #leftMarketSidebar.market-sidebar {
    display: none !important;
  }
}



/* ================================================================
   LEFT CONTEXT SIDEBAR — layout bridge
   ================================================================ */
body.left-context-open #sidebarBackdrop {
  display: none;
}
body.left-context-open #gaemiWorkspace {
  min-width: 0;
}
@media (max-width: 1023px) {
  body.left-context-open #leftMarketSidebar.market-sidebar {
    display: none !important;
  }
  body.left-context-open #sidebarBackdrop {
    display: block;
  }
}


/* 관련 기사 출처 칩 — 다른 출처 버튼과 같은 작고 둥근 형태 */
.news-source-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 32px;
  margin-top: 4px;
  padding: 0 10px 0 6px;
  border: 1px solid #d4d4d8;
  border-radius: 999px;
  background: #f4f4f5;
  color: #52525b;
  font: inherit;
  font-size: 12px;
  font-weight: 700;
  cursor: pointer;
  transition: border-color .15s ease, background .15s ease, color .15s ease;
}
.news-source-chip:hover {
  border-color: #a1a1aa;
  background: #e4e4e7;
  color: #18181b;
}
.dark .news-source-chip {
  border-color: #303136;
  background: #202124;
  color: var(--gtp-text-2);
}
.dark .news-source-chip:hover {
  border-color: #52525b;
  background: #27272a;
  color: var(--gtp-text);
}
.news-source-chip__badges { display: inline-flex; align-items: center; }
.news-source-chip__badge {
  width: 22px; height: 22px;
  display: inline-flex; align-items: center; justify-content: center;
  margin-left: -3px;
  border: 2px solid #f4f4f5;
  border-radius: 50%;
  background: #d4d4d8;
  color: #3f3f46;
  font-size: 8px;
  font-weight: 800;
}
.news-source-chip__badge:first-child { margin-left: 0; }
.dark .news-source-chip__badge {
  border-color: #202124;
  background: #3f3f46;
  color: var(--gtp-text);
}
.news-source-chip__label { white-space: nowrap; }


/* Stock analysis loading: shared central-chat flow for desktop and mobile. */
.analysis-loading-sequence {
  width: 100%;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: flex-start;
  padding: 8px 0 0;
  text-align: left;
}
.analysis-loading-message {
  display: none;
  font-size: var(--gtp-type-body);
  font-weight: 500;
  letter-spacing: -.02em;
}
.analysis-loading-message.is-visible { display: inline-block; }
.analysis-loading-message.is-shimmer {
  color: transparent;
  background: linear-gradient(90deg, var(--gtp-muted) 0%, var(--gtp-muted) 34%, var(--gtp-text) 50%, var(--gtp-muted) 66%, var(--gtp-muted) 100%);
  background-size: 220% 100%;
  background-clip: text;
  -webkit-background-clip: text;
  animation: gaemiLoadingShimmer 1.45s linear infinite;
}
@keyframes gaemiLoadingShimmer {
  from { background-position: 120% 0; }
  to { background-position: -120% 0; }
}


/* US close: headline -> verified 3-index table -> original-article AI brief -> tags.
   Reuses existing gtp-chat-copy, typing-cursor and reply action components. */
.gaemi-us-close-reply {
  width: 100%;
  min-width: 0;
  white-space: normal;
  overflow-wrap: break-word;
}
.gaemi-us-close-issue + .gaemi-us-close-issue { margin-top: 24px; }
.gaemi-us-close-title {
  margin: 0 0 14px;
  font-weight: 700;
  line-height: 1.6;
  color: var(--gtp-text);
}
.gaemi-us-close-table-wrap {
  width: 100%;
  max-width: 100%;
  margin: 0 0 18px;
  border: 1px solid var(--gtp-border-strong);
  border-radius: 12px;
  overflow: hidden;
}
.gaemi-us-close-index-table {
  border-collapse: collapse;
  width: 100%;
  font-size: .94em;
  line-height: 1.55;
  font-variant-numeric: tabular-nums;
}
.gaemi-us-close-index-table th,
.gaemi-us-close-index-table td {
  padding: 8px 11px;
  text-align: right;
  white-space: nowrap;
}
.gaemi-us-close-index-table th:first-child {
  text-align: left;
  white-space: normal;
}
.gaemi-us-close-index-table thead {
  background: rgba(127, 127, 127, .07);
  color: var(--gtp-text-2);
}
.gaemi-us-close-index-table tbody tr + tr {
  border-top: 1px solid var(--gtp-border);
}
.gaemi-us-close-index-table tbody th {
  color: var(--gtp-text);
  font-weight: 550;
}
.gaemi-us-close-index-table td {
  color: var(--gtp-text);
}
.gaemi-us-close-index-table td.gaemi-us-close-up { color: #dd525b; }
.gaemi-us-close-index-table td.gaemi-us-close-down { color: #4a91dc; }
.gaemi-us-close-summary {
  margin: 0 0 14px;
  white-space: pre-wrap;
}
/* Only newly generated model-2 free-text editorials get this model-3-style
   paragraph/list/heading layout; legacy US-close rows remain unchanged. */
.gaemi-us-close-body { margin: 0 0 14px; overflow-wrap: break-word; }
.gaemi-us-close-paragraph { margin: 0 0 .8em; line-height: 1.76; white-space: pre-wrap; }
.gaemi-us-close-subheading {
  margin: 1.2em 0 .48em;
  font-weight: 750;
  font-size: 1.06em;
  line-height: 1.5;
}
.gaemi-us-close-body > :first-child { margin-top: 0; }
.gaemi-us-close-list {
  padding-left: 0;
  margin: 0 0 .85em;
  list-style-position: inside;
}
.gaemi-us-close-list li { margin: .32em 0; line-height: 1.72; white-space: pre-wrap; }
.gaemi-us-close-tags {
  margin: 0;
  color: var(--gtp-text-2);
}
@media (max-width: 430px) {
  .gaemi-us-close-index-table { font-size: .87em; }
  .gaemi-us-close-index-table th,
  .gaemi-us-close-index-table td { padding: 8px 5px; }
  .gaemi-us-close-index-table th:first-child { padding-left: 9px; }
  .gaemi-us-close-index-table td:last-child { padding-right: 9px; }
}

css/chat-tools.css:
/* Central chat + tools menu.
   Shared only by tools launched from the central chat composer. */

.stock-tools-trigger {
  position: absolute;
  left: 8px;
  top: 50%;
  transform: translateY(-50%);
  z-index: 3;
  width: 36px;
  height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--gtp-muted);
  font-size: 25px;
  font-weight: 300;
  line-height: 1;
  cursor: pointer;
  transition: background .16s ease, color .16s ease;
}

.stock-tools-trigger:hover,
.stock-tools-trigger[aria-expanded="true"] {
  background: var(--gtp-hover);
  color: var(--gtp-text);
}

.stock-tools-trigger:focus-visible,
.stock-tools-menu__item:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

#bottomStockInput.stock-tools-enabled {
  padding-left: 54px;
}

.stock-tools-menu {
  position: absolute;
  left: 0;
  bottom: calc(100% + 10px);
  z-index: 60;
  width: min(380px, calc(100vw - 32px));
  max-height: min(420px, calc(100dvh - 160px));
  overflow-y: auto;
  padding: 6px;
  border: 1px solid var(--gtp-border);
  border-radius: 16px;
  background: var(--gtp-surface);
  box-shadow: var(--gtp-shadow);
}

.stock-tools-menu[hidden] {
  display: none;
}

.stock-tools-menu__item {
  width: 100%;
  min-height: 42px;
  padding: 8px 11px;
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  gap: 12px;
  border: 0;
  border-radius: 11px;
  background: transparent;
  color: var(--gtp-text);
  text-align: left;
  cursor: pointer;
}

.stock-tools-menu__item:hover {
  background: var(--gtp-hover);
}

.stock-tools-menu__title {
  flex: 0 0 auto;
  font-size: 14px;
  font-weight: 750;
  letter-spacing: -0.02em;
  white-space: nowrap;
}

.stock-tools-menu__desc {
  min-width: 0;
  flex: 1 1 auto;
  overflow: hidden;
  color: var(--gtp-muted);
  font-size: 11px;
  font-weight: 600;
  line-height: 1.2;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.chat-tool-close {
  flex: 0 0 auto;
  width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--gtp-muted);
  cursor: pointer;
  transition: background .16s ease, color .16s ease;
}

.chat-tool-close:hover {
  background: var(--gtp-hover);
  color: var(--gtp-text);
}

.chat-tool-close:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

.chat-tool-close svg {
  width: 16px;
  height: 16px;
}

@media (max-width: 520px) {
  .stock-tools-menu {
    width: calc(100vw - 32px);
  }

  .stock-tools-menu__item {
    gap: 10px;
  }

  .stock-tools-menu__title {
    font-size: 13px;
  }

  .stock-tools-menu__desc {
    font-size: 11px;
  }
}


/* Central news: related-stock range from the article timestamp through its first reaction session. */
.news-reaction {
  width: min(430px, 100%);
  margin-top: 2px;
  display: grid;
  gap: 7px;
  color: var(--gtp-text-2);
  font-family: var(--gtp-font-family);
}

.news-reaction[hidden] {
  display: none;
}

.news-reaction__title {
  margin: 0 0 1px;
  color: var(--gtp-muted);
  font-size: var(--gtp-type-body);
  font-weight: 600;
  line-height: 1.4;
}

.news-reaction__row {
  display: grid;
  grid-template-columns: minmax(72px, auto) 78px minmax(110px, 1fr) 78px;
  align-items: center;
  gap: 9px;
  min-height: 20px;
}

.news-reaction__name,
.news-reaction__value {
  font-size: var(--gtp-type-body);
  font-weight: 600;
  line-height: 1.25;
}

.news-reaction__name {
  min-width: 0;
  overflow: hidden;
  color: var(--gtp-text-2);
  text-overflow: ellipsis;
  white-space: nowrap;
}

.news-reaction__row--name-only .news-reaction__name {
  grid-column: 1 / -1;
}

.news-reaction__value {
  text-align: center;
  white-space: nowrap;
}

.news-reaction__bar {
  position: relative;
  display: block;
  height: 12px;
}

.news-reaction__bar::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 1px;
  background: var(--gtp-border-strong);
  transform: translateY(-50%);
}

.news-reaction__bar::after {
  content: "";
  position: absolute;
  inset: 3px 0;
  border-left: 1px solid var(--gtp-muted);
  border-right: 1px solid var(--gtp-muted);
}

.news-reaction__value--up {
  color: #f472b6;
}

.news-reaction__value--down {
  color: #38bdf8;
}

.news-reaction__value--flat {
  color: var(--gtp-muted);
}

@media (max-width: 520px) {
  .news-reaction__row {
    grid-template-columns: minmax(64px, 80px) 70px minmax(84px, 1fr) 70px;
    gap: 7px;
  }
}

css/memo-pad.css:
/* Central chat memo pad only. */

.memo-pad-message {
  width: 100%;
  min-width: 0;
  animation: memoPadPop .18s cubic-bezier(.2, .8, .2, 1);
}

@keyframes memoPadPop {
  from {
    opacity: 0;
    transform: translateY(6px) scale(.995);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.memo-pad-card {
  width: 100%;
  min-width: 0;
  color: var(--gtp-text);
  user-select: text;
}

.memo-pad-card button,
.memo-pad-card textarea {
  user-select: auto;
}

.memo-pad-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.memo-pad-title {
  margin: 0;
  color: var(--gtp-text);
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.025em;
  line-height: 1.35;
}

.memo-pad-subtitle {
  margin: 3px 0 0;
  color: var(--gtp-muted);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.45;
}

.memo-pad-head-actions {
  flex: 0 0 auto;
  display: flex;
  align-items: flex-start;
  gap: 4px;
}

.memo-pad-status {
  flex: 0 0 auto;
  min-height: 18px;
  color: var(--gtp-muted);
  font-size: 11px;
  font-weight: 700;
  line-height: 18px;
}

.memo-pad-textarea {
  display: block;
  width: 100%;
  min-height: 160px;
  max-height: 420px;
  resize: none;
  overflow-y: auto;
  padding: 14px 15px;
  border: 1px solid var(--gtp-border);
  border-radius: 14px;
  background: var(--gtp-surface);
  color: var(--gtp-text);
  font: inherit;
  font-size: 15px;
  font-weight: 550;
  line-height: 1.65;
  letter-spacing: -0.012em;
  outline: none;
  transition: border-color .16s ease, background .16s ease;
}

.memo-pad-textarea::placeholder {
  color: var(--gtp-faint);
  font-weight: 550;
}

.memo-pad-textarea:focus {
  border-color: var(--gtp-border-strong);
  background: var(--gtp-surface-2);
}

.memo-pad-textarea:focus-visible,
.memo-pad-button:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

.memo-pad-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 10px;
}

.memo-pad-actions__right {
  display: flex;
  align-items: center;
  gap: 8px;
}

.memo-pad-button {
  height: 38px;
  padding: 0 14px;
  border-radius: 11px;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: background .16s ease, color .16s ease, opacity .16s ease, transform .16s ease;
}

.memo-pad-button:active {
  transform: translateY(1px);
}

.memo-pad-button--quiet {
  border: 1px solid var(--gtp-border);
  background: transparent;
  color: var(--gtp-muted);
}

.memo-pad-button--quiet:hover {
  background: var(--gtp-hover);
  color: var(--gtp-text);
}

.memo-pad-button--primary {
  border: 1px solid var(--gtp-border-strong);
  background: var(--gtp-text);
  color: var(--gtp-surface);
}

.memo-pad-button--primary:hover {
  opacity: .9;
}

@media (max-width: 520px) {
  .memo-pad-head {
    gap: 8px;
  }

  .memo-pad-textarea {
    min-height: 150px;
  }
}

