.sketch-pad-tool:focus-visible,
.sketch-pad-icon:focus-visible,
.sketch-pad-color:focus-visible,
.sketch-pad-size input:focus-visible,
.sketch-pad-button:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

.sketch-pad-canvas-wrap {
  width: 100%;
  overflow: hidden;
  border: 1px solid var(--gtp-border);
  border-radius: 14px;
  background: #fff;
}

.sketch-pad-canvas {
  display: block;
  width: 100%;
  max-width: 100%;
  background: #fff;
  cursor: crosshair;
  touch-action: none;
}

.sketch-pad-canvas.is-erasing {
  cursor: cell;
}

.sketch-pad-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  margin-top: 10px;
}

.sketch-pad-button {
  height: 38px;
  padding: 0 14px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  border-radius: 11px;
  font-size: 12px;
  font-weight: 800;
  cursor: pointer;
  transition: background .16s ease, color .16s ease, opacity .16s ease, transform .16s ease;
}

.sketch-pad-button:active {
  transform: translateY(1px);
}

.sketch-pad-button--quiet {
  border: 1px solid var(--gtp-border);
  background: transparent;
  color: var(--gtp-muted);
}

.sketch-pad-button--quiet:hover {
  background: var(--gtp-hover);
  color: var(--gtp-text);
}

.sketch-pad-button--primary {
  border: 1px solid var(--gtp-border-strong);
  background: var(--gtp-text);
  color: var(--gtp-surface);
}

.sketch-pad-button--primary:hover {
  opacity: .9;
}

@media (max-width: 520px) {
  .sketch-pad-toolbar {
    gap: 6px;
    padding: 6px;
  }

  .sketch-pad-tool {
    padding: 0 8px;
  }

  .sketch-pad-tool span {
    display: none;
  }

  .sketch-pad-size span {
    display: none;
  }

  .sketch-pad-size input {
    width: 70px;
  }

  .sketch-pad-canvas-wrap {
    border-radius: 12px;
  }
}

css/stock-calculator.css:
/* Central chat stock calculator.
   The calculator belongs to the chat composer/chat body only; no sidebar or panel styles live here. */

.stock-calculator-tab:focus-visible,
.stock-calculator-input:focus-visible,
.stock-calculator-action:focus-visible {
  outline: 2px solid #38bdf8;
  outline-offset: 2px;
}

.stock-calculator-message {
  width: 100%;
  min-width: 0;
  animation: stockCalculatorFade .2s ease-out;
}

@keyframes stockCalculatorFade {
  from { opacity: 0; transform: translateY(4px); }
  to { opacity: 1; transform: translateY(0); }
}

.stock-calculator-card {
  width: 100%;
  min-width: 0;
  color: var(--gtp-text);
  user-select: text;
}

.stock-calculator-card button,
.stock-calculator-card input {
  user-select: auto;
}

.stock-calculator-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.stock-calculator-title {
  margin: 0;
  color: var(--gtp-text);
  font-size: 17px;
  font-weight: 800;
  letter-spacing: -0.025em;
  line-height: 1.35;
}

.stock-calculator-subtitle {
  margin: 3px 0 0;
  color: var(--gtp-muted);
  font-size: 12px;
  font-weight: 600;
  line-height: 1.45;
}

.stock-calculator-tabs {
  display: flex;
  gap: 2px;
  overflow-x: auto;
  border-bottom: 1px solid var(--gtp-border);
  margin-bottom: 18px;
}

.stock-calculator-tab {
  flex: 0 0 auto;
  min-height: 40px;
  padding: 0 12px;
  border: 0;
  border-bottom: 2px solid transparent;
  background: transparent;
  color: var(--gtp-muted);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}

.stock-calculator-tab:hover {
  color: var(--gtp-text);
}

.stock-calculator-tab.is-active {
  border-bottom-color: var(--gtp-text);
  color: var(--gtp-text);
}

.stock-calculator-fields {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.stock-calculator-field {
  min-width: 0;
}

.stock-calculator-label {
  display: block;
  margin-bottom: 6px;
  color: var(--gtp-muted);
  font-size: 12px;
  font-weight: 700;
}

.stock-calculator-input {
  width: 100%;
  height: 44px;
  min-width: 0;
  padding: 0 13px;
  border: 1px solid var(--gtp-border);
  border-radius: 12px;
  background: var(--gtp-surface);
  color: var(--gtp-text);
  font: inherit;
  font-size: 16px;
  font-weight: 650;
  letter-spacing: -0.015em;
  outline: none;
  transition: border-color .16s ease, background .16s ease;
}

.stock-calculator-input::placeholder {
  color: var(--gtp-faint);
  font-weight: 550;
}

.stock-calculator-input:focus {
  border-color: var(--gtp-border-strong);
  background: var(--gtp-surface-2);
}

.stock-calculator-validation {
  min-height: 20px;
  margin-top: 8px;
  color: #ef4444;
  font-size: 12px;
  font-weight: 650;
}

.dark .stock-calculator-validation {
  color: #f87171;
}

.stock-calculator-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 4px;
}

.stock-calculator-action {
  min-width: 82px;
  height: 40px;
  padding: 0 17px;
  border: 1px solid var(--gtp-border-strong);
  border-radius: 12px;
  background: var(--gtp-text);
  color: var(--gtp-surface);
  font-size: 13px;
  font-weight: 800;
  cursor: pointer;
  transition: opacity .16s ease, transform .16s ease;
}

.stock-calculator-action:hover {
  opacity: .9;
}

.stock-calculator-action:active {
  transform: translateY(1px);
}

.stock-calculator-result {
  margin-top: 18px;
  padding-top: 14px;
  border-top: 1px solid var(--gtp-border);
}

.stock-calculator-result[hidden] {
  display: none;
}

.stock-calculator-result-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 4px;
}

.stock-calculator-result-title {
  color: var(--gtp-muted);
  font-size: 12px;
  font-weight: 750;
}

.stock-calculator-result-row {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 16px;
  padding: 7px 0;
}

.stock-calculator-result-label {
  min-width: 0;
  color: var(--gtp-muted);
  font-size: 13px;
  font-weight: 650;
}

.stock-calculator-result-value {
  min-width: 0;
  color: var(--gtp-text);
  font-size: 15px;
  font-weight: 800;
  text-align: right;
  overflow-wrap: anywhere;
}

.stock-calculator-result-row.is-primary .stock-calculator-result-value {
  font-size: 19px;
  letter-spacing: -0.025em;
}

@media (max-width: 520px) {
  .stock-calculator-fields {
    grid-template-columns: 1fr;
  }
  .stock-calculator-tab {
    padding-inline: 10px;
  }
}
